def confusion(y, yhat):
    y, yhat = np.asarray(y), np.asarray(yhat)
    return np.array([[np.sum((y == 0) & (yhat == 0)), np.sum((y == 0) & (yhat == 1))],
                     [np.sum((y == 1) & (yhat == 0)), np.sum((y == 1) & (yhat == 1))]])

def precision_recall_f1(y, yhat):
    (tn, fp), (fn, tp) = confusion(y, yhat)
    p = tp / (tp + fp) if tp + fp else 0.0
    r = tp / (tp + fn) if tp + fn else 0.0
    f = 2 * p * r / (p + r) if p + r else 0.0
    return p, r, f

def roc_points(y, score):
    y, score = np.asarray(y), np.asarray(score)
    order = np.argsort(-score, kind='mergesort')
    s, t = score[order], y[order]
    distinct = np.r_[np.where(np.diff(s))[0], len(s) - 1]
    tps = np.cumsum(t)[distinct]
    fps = (distinct + 1) - tps
    return np.r_[0, fps / (len(t) - t.sum())], np.r_[0, tps / t.sum()]

def auc_trapz(fpr, tpr):
    return float(np.sum(np.diff(fpr) * (tpr[1:] + tpr[:-1]) / 2))

