def threshold_for_recall(y, score, target):
    y, score = np.asarray(y), np.asarray(score)
    for t in np.sort(np.unique(score))[::-1]:
        if (score[y == 1] >= t).mean() >= target:
            return float(t)
    return float(score.min())

