def distance_contrast(n, d, seed, queries=20):
    X = np.random.default_rng(seed).random((n, d))
    out = []
    for i in range(queries):
        dist = np.sqrt(((np.delete(X, i, axis=0) - X[i]) ** 2).sum(axis=1))
        out.append((dist.max() - dist.min()) / dist.min())
    return float(np.mean(out))

