def fit_gnb(X, y):
    classes = np.unique(y)
    eps = 1e-9 * X.var(axis=0).max()
    return {'classes': classes,
            'prior': np.array([np.mean(y == c) for c in classes]),
            'mean': np.array([X[y == c].mean(axis=0) for c in classes]),
            'var': np.array([X[y == c].var(axis=0) + eps for c in classes])}

def predict_log_proba_gnb(model, X):
    jll = np.log(model['prior']) - 0.5 * np.sum(np.log(2 * np.pi * model['var']), axis=1) \
          - 0.5 * (((X[:, None, :] - model['mean']) ** 2) / model['var']).sum(axis=2)
    return jll - logsumexp(jll, axis=1, keepdims=True)

