exercises.solution:
def svm_objective(w, b, X, y, C):
    return 0.5 * w @ w + C * np.maximum(0, 1 - y * (X @ w + b)).sum()

def svm_subgrad(w, b, X, y, C):
    active = y * (X @ w + b) < 1
    gw = w - C * (y[active, None] * X[active]).sum(axis=0)
    gb = -C * y[active].sum()
    return gw, gb

def train_svm(X, y, C, steps=3000, lr0=0.01):
    w, b = np.zeros(X.shape[1]), 0.0
    best = (svm_objective(w, b, X, y, C), w.copy(), b)
    for t in range(1, steps + 1):
        gw, gb = svm_subgrad(w, b, X, y, C)
        lr = lr0 / np.sqrt(t)
        w, b = w - lr * gw, b - lr * gb
        value = svm_objective(w, b, X, y, C)
        if value < best[0]:
            best = (value, w.copy(), b)
    return best[1], best[2]

